components-block-steps-steps--steps-defa.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlStepsComponent } from '@domg-wc/components/block';

// vl-steps registreert zelf vl-step en vl-duration-step; @domg-wc/components/block exporteert enkel VlStepsComponent.
registerWebComponents([VlStepsComponent]);

components-block-steps-steps--steps-icon.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlIconComponent } from '@domg-wc/components/atom';
import { VlStepsComponent } from '@domg-wc/components/block';

// vl-step registreert via vl-accordion ook vl-icon, maar je gebruikt vl-icon hier zelf in het slot icon: registreer
// het dan ook zelf.
registerWebComponents([VlStepsComponent, VlIconComponent]);

components-block-steps-steps--steps-side.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlTitleComponent } from '@domg-wc/components/atom';
import { VlSideNavigationComponent, VlStepsComponent } from '@domg-wc/components/block';

// De story registreert enkel VlSideNavigationComponent (vl-steps via zijn import). vl-title komt uit
// @domg-wc/components/atom en registreer je zelf.
registerWebComponents([VlStepsComponent, VlSideNavigationComponent, VlTitleComponent]);
